-- Test account: teacher2@test.com / password123.
-- Hash generated by the real apps/api/src/auth.ts hashPassword() helper (Argon2id).
-- Paste the entire transaction into Supabase SQL Editor. No admin grants change.
BEGIN;
SET LOCAL search_path = public;
SELECT pg_advisory_xact_lock(1095782480, 1501);
DO $fixture$
DECLARE
  tenant UUID := 'cf463143-ab36-4fad-820b-bca37723a1ef';
  test_user UUID := 'f1500000-0000-4000-8000-000000000001';
  test_member UUID := 'f1500000-0000-4000-8000-000000000002';
  anchor UUID := 'f1500000-0000-4000-8000-000000000003';
  assigned UUID := 'f1500000-0000-4000-8000-000000000004';
  unassigned UUID := 'f1500000-0000-4000-8000-000000000005';
  reader_role UUID;
  permission_id_value UUID;
  permission_key_value TEXT;
  scope_value TEXT;
  anchor_type TEXT;
  target_type TEXT;
  item RECORD;
BEGIN
  PERFORM 1 FROM organizations WHERE id = tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'Test organization does not exist'; END IF;

  -- This route uses user.read only when ai.chat is absent. Do not silently
  -- broaden a role that the test requires to contain exactly two permissions.
  IF EXISTS (SELECT 1 FROM organization_permissions WHERE organization_id = tenant AND permission_key = 'ai.chat') THEN
    RAISE EXCEPTION 'ai.chat is configured: the chat route requires an explicit ai.chat grant, incompatible with this exact two-permission fixture';
  END IF;

  SELECT COALESCE(from_entity_type, 'membership'), to_entity_type
  INTO STRICT anchor_type, target_type FROM relationship_types
  WHERE organization_id = tenant AND type_key = 'assigned_to';
  IF anchor_type NOT IN ('membership', 'staff') OR (target_type IS NOT NULL AND target_type <> 'student') THEN
    RAISE EXCEPTION 'Unexpected assigned_to endpoint constraints: % -> %', anchor_type, target_type;
  END IF;

  -- Reject collisions with an unrelated account rather than repurpose it.
  IF EXISTS (SELECT 1 FROM users WHERE (id = test_user OR lower(email) = 'teacher2@test.com')
    AND NOT (id = test_user AND email = 'teacher2@test.com')) THEN
    RAISE EXCEPTION 'teacher2@test.com or fixture user UUID already belongs to another account';
  END IF;
  INSERT INTO users(id, email, password_hash, account_status)
  SELECT test_user, 'teacher2@test.com',
    '$argon2id$v=19$m=65536,t=3,p=4$CGuOMZPi0yV9ZGMjK5ml+Q$pi50rQAn+ictka54jC82Tuqgj3cb4nDC+DZPkm4EB04', 'active'
  WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = test_user);
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = test_user AND account_status = 'active'
    AND password_hash = '$argon2id$v=19$m=65536,t=3,p=4$CGuOMZPi0yV9ZGMjK5ml+Q$pi50rQAn+ictka54jC82Tuqgj3cb4nDC+DZPkm4EB04') THEN
    RAISE EXCEPTION 'Existing fixture account status/password changed; refusing to reset it';
  END IF;

  IF EXISTS (SELECT 1 FROM memberships WHERE (id = test_member OR user_id = test_user)
    AND NOT (id = test_member AND user_id = test_user AND organization_id = tenant AND status = 'active')) THEN
    RAISE EXCEPTION 'Unexpected fixture membership or additional tenant membership';
  END IF;
  INSERT INTO memberships(id, organization_id, user_id, status)
  SELECT test_member, tenant, test_user, 'active'
  WHERE NOT EXISTS (SELECT 1 FROM memberships WHERE id = test_member);

  INSERT INTO organization_roles(organization_id, role_key, display_name)
  SELECT tenant, 'teacher_assigned_reader', 'Teacher assigned reader'
  WHERE NOT EXISTS (SELECT 1 FROM organization_roles WHERE organization_id = tenant AND role_key = 'teacher_assigned_reader');
  SELECT id INTO STRICT reader_role FROM organization_roles
  WHERE organization_id = tenant AND role_key = 'teacher_assigned_reader';

  FOREACH permission_key_value IN ARRAY ARRAY['user.read', 'student.read'] LOOP
    scope_value := CASE permission_key_value WHEN 'user.read' THEN 'own_user' ELSE 'assigned_entity' END;
    INSERT INTO organization_permissions(organization_id, permission_key)
    SELECT tenant, permission_key_value WHERE NOT EXISTS (
      SELECT 1 FROM organization_permissions WHERE organization_id = tenant AND permission_key = permission_key_value);
    SELECT id INTO STRICT permission_id_value FROM organization_permissions
    WHERE organization_id = tenant AND permission_key = permission_key_value;
    INSERT INTO organization_role_permissions(organization_id, role_id, permission_id, scope)
    SELECT tenant, reader_role, permission_id_value, scope_value WHERE NOT EXISTS (
      SELECT 1 FROM organization_role_permissions WHERE organization_id = tenant AND role_id = reader_role
        AND permission_id = permission_id_value AND scope = scope_value);
  END LOOP;

  IF EXISTS (SELECT 1 FROM organization_role_permissions rp
    LEFT JOIN organization_permissions p ON p.organization_id = rp.organization_id AND p.id = rp.permission_id
    WHERE rp.organization_id = tenant AND rp.role_id = reader_role
      AND NOT (COALESCE(p.permission_key = 'user.read' AND rp.scope = 'own_user', false)
        OR COALESCE(p.permission_key = 'student.read' AND rp.scope = 'assigned_entity', false))) THEN
    RAISE EXCEPTION 'teacher_assigned_reader has extra grants; shared role was not changed';
  END IF;
  IF EXISTS (SELECT 1 FROM membership_roles WHERE membership_id = test_member)
    OR EXISTS (SELECT 1 FROM organization_membership_roles WHERE membership_id = test_member
      AND (organization_id <> tenant OR role_id <> reader_role)) THEN
    RAISE EXCEPTION 'Fixture membership has legacy or additional roles; refusing to alter them';
  END IF;
  INSERT INTO organization_membership_roles(organization_id, membership_id, role_id)
  SELECT tenant, test_member, reader_role WHERE NOT EXISTS (
    SELECT 1 FROM organization_membership_roles WHERE organization_id = tenant AND membership_id = test_member AND role_id = reader_role);

  FOR item IN SELECT * FROM (VALUES (anchor_type, 'Scope test anchor'), ('student', 'Student')) AS t(type_key, display_name) LOOP
    INSERT INTO entity_types(organization_id, type_key, display_name)
    SELECT tenant, item.type_key, item.display_name WHERE NOT EXISTS (
      SELECT 1 FROM entity_types WHERE organization_id = tenant AND type_key = item.type_key);
  END LOOP;
  FOR item IN SELECT * FROM (VALUES
    (anchor, anchor_type, jsonb_build_object('name', 'Scope Test Teacher', 'user_id', test_user, 'fixture', 'assigned_scope_v1')),
    (assigned, 'student', jsonb_build_object('name', 'Scope Assigned Student', 'fixture', 'assigned_scope_v1')),
    (unassigned, 'student', jsonb_build_object('name', 'Scope Unassigned Student', 'fixture', 'assigned_scope_v1'))
  ) AS t(id, entity_type, data) LOOP
    IF EXISTS (SELECT 1 FROM entities e WHERE e.id = item.id
      AND (e.organization_id <> tenant OR e.entity_type <> item.entity_type OR e.data <> item.data)) THEN
      RAISE EXCEPTION 'Fixture entity UUID collision or modified fixture: %', item.id;
    END IF;
    INSERT INTO entities(id, organization_id, entity_type, data)
    SELECT item.id, tenant, item.entity_type, item.data WHERE NOT EXISTS (SELECT 1 FROM entities WHERE id = item.id);
  END LOOP;
  IF EXISTS (SELECT 1 FROM membership_entities WHERE
    (membership_id = test_member OR entity_id = anchor)
    AND NOT (organization_id = tenant AND membership_id = test_member AND entity_id = anchor)) THEN
    RAISE EXCEPTION 'Unexpected fixture anchor mapping';
  END IF;
  INSERT INTO membership_entities(organization_id, membership_id, entity_id)
  SELECT tenant, test_member, anchor WHERE NOT EXISTS (
    SELECT 1 FROM membership_entities WHERE organization_id = tenant AND membership_id = test_member AND entity_id = anchor);
  IF EXISTS (SELECT 1 FROM relationships WHERE organization_id = tenant AND from_entity_id = anchor
    AND relationship_type = 'assigned_to' AND active AND to_entity_id <> assigned) THEN
    RAISE EXCEPTION 'Fixture anchor already has another active assignment';
  END IF;
  INSERT INTO relationships(organization_id, relationship_type, from_entity_id, to_entity_id, context, active)
  SELECT tenant, 'assigned_to', anchor, assigned, '{"fixture":"assigned_scope_v1"}'::jsonb, true
  WHERE NOT EXISTS (SELECT 1 FROM relationships WHERE organization_id = tenant
    AND relationship_type = 'assigned_to' AND from_entity_id = anchor AND to_entity_id = assigned AND active);
END $fixture$;
COMMIT;

SELECT u.email, r.role_key, p.permission_key, rp.scope
FROM users u JOIN memberships m ON m.user_id = u.id
JOIN organization_membership_roles mr ON mr.membership_id = m.id AND mr.organization_id = m.organization_id
JOIN organization_roles r ON r.id = mr.role_id AND r.organization_id = mr.organization_id
JOIN organization_role_permissions rp ON rp.role_id = r.id AND rp.organization_id = r.organization_id
JOIN organization_permissions p ON p.id = rp.permission_id AND p.organization_id = rp.organization_id
WHERE u.id = 'f1500000-0000-4000-8000-000000000001'
ORDER BY p.permission_key;
